window.RP_SESSION={"id":"S-eea8e1426058","messages":[{"id":"RP-II-0181380","time":"2026-09-06T18:52:00+09:00","room":"RP II","name":"진 프테라리온","profile":"헥터","identity":"reviewed","type":"dialogue","body":"-넌 최악이야\n-이기적인 놈\n-멍청한 년\n' 그래 안다고 알아.. '\n\n생각을 정리해보자..\n.\n.\n.\n내 이름은 진 프테르리온.\n\n뭐 이정도로 산 엘프라면 누구나 알겠지.\n재능있다는 소리를 들었고,\n사랑에도 빠져봤지,\n소중한 사람들을 잃었고,\n한가지에 몰두하다 시간만 버리고,\n또 큰 교훈도 얻었지,\n-조심해!\n그래 한번쯤은 폭발사고도 있었어.\n그리고 정처없이 매일매일매일 떠돌다가.\n그래 지금은..\n\n\" 아으윽.. \"\n\n\" 외상으로 달아줄래? \"\n\n-그래 맥주 3잔.\n\n머리가 깨질것 같아.\n옆구리의 상처는 쑤시고.\n망할..\n\n그러다가..\n어설픈 용맹에 대해서 들었지.\n다음 내용은 다 알거야.\n길드를 찾아갔고,\n부끄럽지만 이 나이에 신입이라니.\n아무튼 이게 새 삶이겠지.\n여기서라면 누구에게도 방해받지 않고 연구를 계속할수 있을거야,\n몇백년간 나홀로 마법을 연구했고.\n뭐 다 실패했지만 실패가 성공의 어머니란 말도 있잖아?\n\n그러니까 난 실패자가 아닐거야..\n난 울지도 않아..\n아...취","characters":["P-5d0982a87f77"]},{"id":"RP-II-0181381","time":"2026-09-06T18:52:00+09:00","room":"RP II","name":"진 프테라리온","profile":"헥터","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5d0982a87f77"]},{"id":"RP-II-0181382","time":"2026-09-06T18:52:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
